function.arguments:
{"script":"function inspect() {
  const all = document.querySelectorAll('*');
  let results = [];
  for (const el of all) {
    const text = el.childNodes.length === 1 && el.childNodes[0].nodeType === 3 ? el.textContent.trim() : '';
    if (text && text.includes('666') && text.includes('1月22')) {
      results.push({tag: el.tagName, role: el.getAttribute('role'), text: text.substring(0, 80), aria: el.getAttribute('aria-label')});
    }
  }
  return results.slice(0, 10);
}
return inspect();"}

